// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { 
        c = new RoundFactory(); 
        c.initialize();
    }
    function testFuzz_property(address ownerCandidate, address newImpl) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(newImpl != address(0));
        vm.assume(ownerCandidate != c.owner());

        vm.prank(ownerCandidate);
        try c.updateRoundImplementation(payable(newImpl)) {
            assertTrue(false, "non-owner should revert");
        } catch {
        }

        address realOwner = c.owner();
        vm.prank(realOwner);
        c.updateRoundImplementation(payable(newImpl));
        assertEq(c.roundImplementation(), newImpl);
    }
}
